import{e as r,ab as a,a1 as n,m as i,r as o,p as s}from"./chunks/framework.BGh0NSIy.js";const u=JSON.parse('{"title":"Monthly Updates [May]","description":"May 2024 updates","frontmatter":{"title":"Monthly Updates [May]","description":"May 2024 updates","date":"2024-05-01T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/may-2024.md","filePath":"posts/may-2024.md"}'),l={name:"posts/may-2024.md"};function h(p,e,f,d,m,g){const t=a("Post");return n(),i("div",null,[o(t,{authors:"nbats"}),e[0]||(e[0]=s('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>These update threads only contain major updates. If you&#39;re interested in seeing all minor changes you can follow our <a href="https://github.com/fmhy/FMHYedit/commits/main" target="_blank" rel="noreferrer">Commits Page</a> on GitHub or <a href="https://redd.it/17f8msf" target="_blank" rel="noreferrer">Updates Channel</a> in Discord.</p></div><h3 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h3><ul><li><p>Added <a href="https://fmhy.net/gaming#multi-game-sites" target="_blank" rel="noreferrer">Multi-Game</a>, <a href="https://fmhy.net/gaming#party-games" target="_blank" rel="noreferrer">Party</a>, <a href="https://fmhy.net/gaming#shooter" target="_blank" rel="noreferrer">Shooter</a>, <a href="https://fmhy.net/gaming#platformer" target="_blank" rel="noreferrer">Platforming</a>, <a href="https://fmhy.net/gaming#simulation" target="_blank" rel="noreferrer">Simulation</a>, <a href="https://fmhy.net/gaming#arcade" target="_blank" rel="noreferrer">Arcade</a>, and <a href="https://fmhy.net/gaming#rpg" target="_blank" rel="noreferrer">RPG</a> sections to Browser Games.</p></li><li><p>Added <a href="https://fmhy.net/educational#med-school" target="_blank" rel="noreferrer">Med School</a>, <a href="https://fmhy.net/educational#philosophy" target="_blank" rel="noreferrer">Philosophy</a>, and <a href="https://fmhy.net/educational#geography-datasets" target="_blank" rel="noreferrer">Geography</a> sections to Education.</p></li><li><p>Added <a href="https://fmhy.net/linux-macos#linux-guides" target="_blank" rel="noreferrer">Linux Guides</a> and <a href="https://fmhy.net/linux-macos#window-managers" target="_blank" rel="noreferrer">Window Managers</a> sections to Linux.</p></li><li><p>Added a <a href="https://fmhy.net/reading#public-domain" target="_blank" rel="noreferrer">Public Domain</a> section to Reading.</p></li><li><p>Added a <a href="https://fmhy.net/educational#german" target="_blank" rel="noreferrer">German</a> section to Language Learning.</p></li><li><p>Renamed Audio Download to <a href="https://fmhy.net/audio#audio-ripping" target="_blank" rel="noreferrer">Audio Ripping</a>, cleaned up the section, and separated sites and tools into their own subsections.</p></li><li><p>Cleaned up the <a href="https://fmhy.net/torrenting#qbittorrent-tools" target="_blank" rel="noreferrer">qBittorrent Tools</a>, <a href="https://fmhy.net/internet-tools#paywall-bypass" target="_blank" rel="noreferrer">Paywall Bypass</a>, <a href="https://fmhy.pages.dev/text-tools#pastebins" target="_blank" rel="noreferrer">Pastebins</a>, and <a href="https://fmhy.net/internet-tools#open-source-intelligence" target="_blank" rel="noreferrer">OSINT</a> sections.</p></li><li><p>Moved <a href="https://fmhy.net/educational#periodic-tables" target="_blank" rel="noreferrer">Periodic Tables</a>, <a href="https://fmhy.net/educational#quote-indexes" target="_blank" rel="noreferrer">Quotes</a>, <a href="https://fmhy.net/privacy#file-scanners" target="_blank" rel="noreferrer">File Scanners</a>, and <a href="https://fmhy.net/audio#sheet-music" target="_blank" rel="noreferrer">Sheet Music</a> out of storage into main sections.</p></li><li><p>Moved <a href="https://fmhy.net/gaming-tools" target="_blank" rel="noreferrer">Gaming Tools</a> out of Gaming onto its own page.</p></li><li><p>Separated <a href="https://fmhy.net/image-tools#painting" target="_blank" rel="noreferrer">Painting</a> and <a href="https://fmhy.net/image-tools#drawing" target="_blank" rel="noreferrer">Drawing</a> into their own sections.</p></li></ul><hr><h3 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h3><ul><li><p>Starred the <a href="https://fmhy.net/system-tools#system-debloating" target="_blank" rel="noreferrer">Debloat Guide</a> in System Debloating. Collaborative project by our Discord members; let us know what you think or if you have any suggestions for it.</p></li><li><p>Starred <a href="https://fmhy.net/video#multi-server" target="_blank" rel="noreferrer">Nunflix</a> in Streaming. Multi-server streaming with fast hosts and a nice UI.</p></li><li><p>Starred <a href="https://fmhy.net/downloading#software-sites" target="_blank" rel="noreferrer">Game Bounty</a> in Software as they&#39;ve started uploading software recently.</p></li><li><p>Starred <a href="https://fmhy.net/video#helpful-sites-tools" target="_blank" rel="noreferrer">FastStream</a> in Streaming Tools. Fragmentation streaming which speeds up browser video buffering.</p></li><li><p>Starred <a href="https://fmhy.net/internet-tools#chat-tools" target="_blank" rel="noreferrer">Mumble</a> in Chat Tools. Old-school voice chat client used and loved by many.</p></li><li><p>Starred <a href="https://fmhy.net/torrenting#torrent-clients" target="_blank" rel="noreferrer">Tixati</a> in Torrent Clients. Simple client still popular in some circles.</p></li><li><p>Starred <a href="https://fmhy.net/gaming-tools#optimization-tools" target="_blank" rel="noreferrer">SpecialK</a> in Gaming Optimization. Feature-rich game optimization tool.</p></li><li><p>Starred <a href="https://fmhy.net/image-tools#image-viewers" target="_blank" rel="noreferrer">qView</a> in Image Viewers. Minimal and efficient open-source image viewer.</p></li><li><p>Starred <a href="https://fmhy.net/image-tools#reverse-image-search" target="_blank" rel="noreferrer">SauceNAO</a> in Reverse Image Search. Multi-site search engine.</p></li><li><p>Starred <a href="https://fmhy.net/system-tools#os-emulators" target="_blank" rel="noreferrer">Puter</a> in OS Emulators. Session-saving browser operating system.</p></li><li><p>Starred <a href="https://fmhy.net/storage#minecraft-servers" target="_blank" rel="noreferrer">playit.gg</a> in Minecraft Servers. Easy-to-set-up Minecraft servers.</p></li><li><p>Starred <a href="https://fmhy.net/gaming-tools#minecraft-tools" target="_blank" rel="noreferrer">MCPropertyEncyclopedia</a> in Minecraft Tools. Comprehensive block info database.</p></li><li><p>Starred <a href="https://fmhy.net/audio#song-identification" target="_blank" rel="noreferrer">Shazam + WatZatSong</a> in Song Identification. Popular song identification tools.</p></li></ul><hr><h3 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h3><ul><li>Removed MrGamingStreams as they&#39;ve shut down.</li><li>Removed IDM Activation Script as it&#39;s been archived.</li></ul>',9))])}const y=r(l,[["render",h]]);export{u as __pageData,y as default};
